import type { AppLanguage } from "./types";

export type ResolvedLanguage = Exclude<AppLanguage, "auto">;

export const LANGUAGE_OPTIONS: Array<{ id: AppLanguage; label: string }> = [
  { id: "auto", label: "自动" },
  { id: "zh-CN", label: "简体中文" },
  { id: "zh-TW", label: "繁體中文" },
  { id: "en", label: "English" },
  { id: "ja", label: "日本語" },
  { id: "ko", label: "한국어" }
];

export const LANGUAGE_LABELS: Record<ResolvedLanguage, string> = {
  "zh-CN": "简体中文",
  "zh-TW": "繁體中文",
  en: "English",
  ja: "日本語",
  ko: "한국어"
};

export function resolveLanguage(
  language: AppLanguage | undefined,
  browserLanguage = typeof navigator !== "undefined" ? navigator.language : "zh-CN"
): ResolvedLanguage {
  if (language && language !== "auto") return language;
  const normalized = browserLanguage.toLowerCase();
  if (normalized.startsWith("zh-tw") || normalized.startsWith("zh-hk")) {
    return "zh-TW";
  }
  if (normalized.startsWith("en")) return "en";
  if (normalized.startsWith("ja")) return "ja";
  if (normalized.startsWith("ko")) return "ko";
  return "zh-CN";
}

