export type UiTextKey = keyof (typeof UI_TEXT)["zh-CN"];

export function uiText(
  language: AppLanguage | undefined,
  key: UiTextKey
): string {
  return UI_TEXT[resolveLanguage(language)][key] ?? UI_TEXT["zh-CN"][key];
}
